CREATE OR REPLACE FUNCTION fn_desactivar_aula(p_id_aula BIGINT) RETURNS VOID AS $$ BEGIN -- Toda la operación corre en la transacción implícita de la función. -- Si cualquiera de los dos UPDATE falla, PostgreSQL revierte ambos. UPDATE aula SET estado = 'inactiva', fecha_actualizacion = now() WHERE id_aula = p_id_aula;
IF NOT FOUND THEN RAISE EXCEPTION 'Aula % no existe', p_id_aula; END IF;
UPDATE sensor SET estado = 'inactivo', fecha_actualizacion = now() WHERE id_aula = p_id_aula AND estado <> 'inactivo';
-- COMMIT es implícito al finalizar exitosamente la función. EXCEPTION WHEN OTHERS THEN -- ROLLBACK automático: se relanza el error para que el llamador se entere. RAISE; END; $$ LANGUAGE plpgsql;
